import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long k = nextLong();
        // Group positions by speed: pack (speed, index) into one long and sort.
        long[] v = new long[n];
        for (int i = 0; i < n; i++) v[i] = (nextLong() << 19) | i;
        Arrays.sort(v);
        int mask = (1 << 19) - 1, answer = 0;
        for (int g = 0; g < n;) {
            int e = g;
            while (e < n && (v[e] >> 19) == (v[g] >> 19)) e++;
            // Window over occurrences g..e-1: deletions needed = span - kept.
            int left = g;
            for (int right = g; right < e; right++) {
                while ((long) ((v[right] & mask) - (v[left] & mask)) - (right - left) > k) left++;
                answer = Math.max(answer, right - left + 1);
            }
            g = e;
        }
        System.out.println(answer);
    }
}

