	v := make([]int64, n)
	for i := range v {
		v[i] = nextInt()<<19 | int64(i)
	}
	slices.Sort(v)
	const mask = 1<<19 - 1
	answer := 0
	for g := 0; g < n; {
		e := g
		for e < n && v[e]>>19 == v[g]>>19 {
			e++
		}
		// Window over occurrences g..e-1: deletions needed = span - kept.
		left := g
		for right := g; right < e; right++ {
			for (v[right]&mask)-(v[left]&mask)-int64(right-left) > k {
				left++
			}
			answer = max(answer, right-left+1)
		}
		g = e
	}
	fmt.Println(answer)
